Now I understand the fuzz harness. The relevant part is:

```c
struct mg_mqtt_message mm;
if (mg_mqtt_parse(data, size, 5, &mm) == MQTT_OK) {
    mg_crc32(0, mm.topic.buf, mm.topic.len);
    mg_crc32(0, mm.data.buf, mm.data.len);
    mg_crc32(0, mm.dgram.buf, mm.dgram.len);
    {
      struct mg_mqtt_prop prop;
      size_t ofs = 0;
      while ((ofs = mg_mqtt_next_prop(&mm, &prop, ofs)) > 0) {
          mg_crc32(0, prop.key.buf, prop.key.len);
          mg_crc32(0, prop.val.buf, prop.val.len);
      }
    }
}
```

So the harness parses an MQTT packet with version 5, then iterates over properties with `mg_mqtt_next_prop`. The vulnerability is in `mg_mqtt_next_prop` for `MQTT_PROP_TYPE_BINARY_DATA`:

```c
case MQTT_PROP_TYPE_BINARY_DATA:
  if (i + 2 > end) return 0;
  prop->val.len = (uint16_t) ((((uint16_t) i[0]) << 8) | i[1]);
  prop->val.buf = (char *) i + 2;
  new_pos += 2 + prop->val.len;
  break;
```

Notice that for `MQTT_PROP_TYPE_BINARY_DATA`, there's NO check that `i + 2 + prop->val.len <= end`. Compare with `MQTT_PROP_TYPE_STRING`:

```c
case MQTT_PROP_TYPE_STRING:
  if (i + 2 >= end) return 0;
  prop->val.len = (uint16_t) ((((uint16_t) i[0]) << 8) | i[1]);
  prop->val.buf = (char *) i + 2;
  if (i + 2 + prop->val.len > end) return 0;  // <-- this check exists for STRING
  new_pos += 2 + prop->val.len;
  break;
```

So for BINARY_DATA, the check `if (i + 2 + prop->val.len > end) return 0;` is missing. This means `prop->val.buf` points to `i + 2` and `prop->val.len` can be larger than the remaining bytes. Then in the harness:

```c
mg_crc32(0, prop.val.buf, prop.val.len);
```

This reads `prop->val.len` bytes from `prop->val.buf`, which goes beyond the buffer → heap buffer over-read.

Now I need to construct an MQTT 5 PUBLISH packet that:
1. Parses successfully with `mg_mqtt_parse(data, size, 5, &mm) == MQTT_OK`
2. Has a properties section with a BINARY_DATA property whose declared length exceeds the remaining packet

Let me understand the MQTT packet format and the parsing.

MQTT fixed header:
- byte 0: type (4 bits) + flags (4 bits). For PUBLISH, type = 3 (0x30), and the low nibble has DUP, QoS, RETAIN.
- bytes 1+: remaining length (varint)

For PUBLISH (cmd = 3, MQTT_CMD_PUBLISH):
```c
case MQTT_CMD_PUBLISH: {
  if (p + 2 > end) return MQTT_MALFORMED;
  m->topic.len = (uint16_t) ((((uint16_t) p[0]) << 8) | p[1]);
  m->topic.buf = (char *) p + 2;
  p += 2 + m->topic.len;
  if (p > end) return MQTT_MALFORMED;
  if (m->qos > 0) {
    if (p + 2 > end) return MQTT_MALFORMED;
    m->id = (uint16_t) ((((uint16_t) p[0]) << 8) | p[1]);
    p += 2;
  }
  if (p > end) return MQTT_MALFORMED;
  if (version == 5 && p + 2 < end) {
    len_len =
        (uint32_t) decode_varint(p, (size_t) (end - p), &m->props_size);
    if (!len_len) return MQTT_MALFORMED;
    m->props_start = (size_t) (p + len_len - buf);
    p += len_len + m->props_size;
  }
  if (p > end) return MQTT_MALFORMED;
  m->data.buf = (char *) p;
  m->data.len = (size_t) (end - p);
  break;
}
```

So for a PUBLISH with QoS 0:
- byte 0: 0x30 (PUBLISH, QoS 0, no DUP, no RETAIN) → cmd = 3, qos = 0
- byte 1: remaining length (varint)
- Then topic: 2 bytes length + topic bytes
- Then (version 5, p + 2 < end): properties length varint + properties
- Then data

